# reuse lanczos resampling from previous with clamped edges
import math

def lanc(x,a=3):
 x=abs(x)
 if x<1e-9: return 1
 if x>=a: return 0
 return math.sin(math.pi*x)/(math.pi*x)*math.sin(math.pi*x/a)/(math.pi*x/a)
def res(vals,n):
 m=len(vals); scale=m/n; out=[]
 for i in range(n):
  c=(i+.5)*scale-.5; left=math.ceil(c-3); right=math.floor(c+3); acc=tot=0
  for j in range(left,right+1):
   w=lanc(c-j); jj=min(max(j,0),m-1); acc+=vals[jj]*w; tot+=w
  out.append(max(0,min(255,int(acc/tot+0.5))))
 return out
R=[255,0,0,255];G=[0,255,0,255];B=[0,0,255,255]
for n in range(4,11):
 rows=list(zip(res(R,n),res(G,n),res(B,n)))
 print('n',n,rows)
