func to8(v uint32) uint8 { if v > 65535 { v = 65535 }; return uint8((v + 128) / 257) }

// Minimal uncompressed BMP decoder for common 24/32/8-bit files.
func decodeBMP(data []byte) (image.Image, error) {
    if len(data) < 54 || data[0] != 'B' || data[1] != 'M' { return nil, errors.New("not bmp") }
    rd16 := func(o int) uint16 { return uint16(data[o]) | uint16(data[o+1])<<8 }
    rd32 := func(o int) uint32 { return uint32(data[o]) | uint32(data[o+1])<<8 | uint32(data[o+2])<<16 | uint32(data[o+3])<<24 }
