    planes, bpp, comp := rd16(26), rd16(28), rd32(30); if planes != 1 || comp != 0 || w <= 0 || h <= 0 { return nil, errors.New("unsupported bmp") }
    img := image.NewRGBA(image.Rect(0,0,w,h))
    switch bpp {
    case 24, 32:
        step := int(bpp/8); stride := ((w*step + 3)/4)*4
