    default:
        return nil, errors.New("unsupported bmp")
    }
    return img, nil
}

func lanczos3(x float64) float64 {
    if x < 0 { x = -x }
    if x == 0 { return 1 }
    if x >= 3 { return 0 }
    pix := math.Pi * x
    return (math.Sin(pix)/pix) * (math.Sin(pix/3)/(pix/3))
}

type contrib struct{ idx int; weight float64 }

func contributions(srcN, dstN int) [][]contrib {
    if dstN <= 0 || srcN <= 0 { return nil }
    du := float64(srcN) / float64(dstN)
    scale := du
    if scale < 1 { scale = 1 }
    ru := math.Ceil(scale * 3)
    res := make([][]contrib, dstN)
    for i := 0; i < dstN; i++ {
        fu := (float64(i)+0.5)*du - 0.5
        begin := int(math.Ceil(fu - ru))
        end := int(math.Floor(fu + ru))
        var cs []contrib
        sum := 0.0
        for j := begin; j <= end; j++ {
            if j >= 0 && j < srcN {
                w := lanczos3((float64(j)-fu)/scale) / scale
                if w != 0 { cs = append(cs, contrib{j, w}); sum += w }
            }
        }
        if sum != 0 { for k := range cs { cs[k].weight /= sum } }
        res[i] = cs
    }
    return res
}

func resize(src Bitmap, dstW, dstH int) Bitmap {
    if dstW <= 0 || dstH <= 0 || src.W <= 0 || src.H <= 0 { return Bitmap{} }
    xcs := contributions(src.W, dstW)
    ycs := contributions(src.H, dstH)
    tmp := make([][3]float64, dstW*src.H)
    for y:=0; y<src.H; y++ { for x:=0; x<dstW; x++ { var r,g,b float64; for _,c := range xcs[x] { p:=src.At(c.idx,y); r += float64(p.R)*c.weight; g += float64(p.G)*c.weight; b += float64(p.B)*c.weight }; tmp[y*dstW+x]=[3]float64{r,g,b} } }
    out := Bitmap{W:dstW,H:dstH,Pix:make([]Pixel,dstW*dstH)}
    for y:=0; y<dstH; y++ { for x:=0; x<dstW; x++ { var r,g,b float64; for _,c := range ycs[y] { p:=tmp[c.idx*dstW+x]; r += p[0]*c.weight; g += p[1]*c.weight; b += p[2]*c.weight }; out.Set(x,y,Pixel{round8(r),round8(g),round8(b)}) } }
    return out
}
func round8(v float64) uint8 { if v < 0 { return 0 }; if v > 255 { return 255 }; return uint8(v + 0.5) }

func scaleBitmap(src Bitmap, maxW, maxH, mode int) Bitmap {
    if mode == 0 { return resize(src, maxW, maxH) }
    sw, sh := float64(src.W), float64(src.H)
    mw, mh := float64(maxW), float64(maxH)
    if sw <= 0 || sh <= 0 { return Bitmap{} }
    if mode == 2 { // fit inside box
        sc := math.Min(mw/sw, mh/sh)
        if sc > 1 { // the original scales up for fit when necessary
            // keep it; this matches small wide images better than never enlarging
        }
        nw, nh := int(sw*sc), int(sh*sc)
        if nw < 1 { nw = 1 }; if nh < 1 { nh = 1 }
        return resize(src, nw, nh)
    }
    // fill: cover the box and crop centered.
    sc := math.Max(mw/sw, mh/sh)
    nw, nh := int(math.Ceil(sw*sc)), int(math.Ceil(sh*sc))
    if nw < maxW { nw = maxW }; if nh < maxH { nh = maxH }
    big := resize(src, nw, nh)
    ox, oy := (nw-maxW)/2, (nh-maxH)/2
    out := Bitmap{W:maxW,H:maxH,Pix:make([]Pixel,maxW*maxH)}
    for y:=0; y<maxH; y++ { for x:=0; x<maxW; x++ { out.Set(x,y,big.At(x+ox,y+oy)) } }
    return out
}

func renderClassic(src Bitmap, tc, tr, mode int, goOut bool) (string, error) {
    raw := scaleBitmap(src, tc, tr*2+2, mode)
    if raw.W < 1 || raw.H < 1 { return "", nil }
    rows := (raw.H - 2) / 2
    if rows < 0 { rows = 0 }
    var lines []string
    for row:=0; row<rows; row++ {
        y := row*2 + 2
        if y+1 >= raw.H { break }
        var b strings.Builder
        for x:=0; x<raw.W; x++ { top:=raw.At(x,y); bot:=raw.At(x,y+1); fmt.Fprintf(&b,"\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm▄",top.R,top.G,top.B,bot.R,bot.G,bot.B) }
        b.WriteString("\033[0m\n")
        lines = append(lines,b.String())
    }
    return finishLines(lines, goOut), nil
}

func renderDither(src Bitmap, tc, tr, mode, dMode int, matte Pixel, noBg, goOut bool) (string, error) {
    raw := scaleBitmap(src, tc, tr+1, mode)
    if raw.W < 1 || raw.H < 1 { return "", nil }
    rows := raw.H - 1
    if rows < 0 { rows = 0 }
    palette := []rune(" ░▒▓█")
    if dMode == 2 { palette = []rune(" .:;+=xX$&#") }
    var lines []string
    for y:=0; y<rows; y++ {
        var b strings.Builder
        for x:=0; x<raw.W; x++ { p:=raw.At(x,y); m:=p.R; if p.G>m {m=p.G}; if p.B>m {m=p.B}; idx:=int(m)*len(palette)/256; if idx>=len(palette){idx=len(palette)-1}; if noBg { fmt.Fprintf(&b,"\033[38;2;%d;%d;%dm%c",p.R,p.G,p.B,palette[idx]) } else { fmt.Fprintf(&b,"\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm%c",matte.R,matte.G,matte.B,p.R,p.G,p.B,palette[idx]) } }
        b.WriteString("\033[0m\n")
        lines=append(lines,b.String())
    }
    return finishLines(lines, goOut), nil
}

func finishLines(lines []string, goOut bool) string {
    if !goOut { return strings.Join(lines, "") }
    var out strings.Builder
    for _, line := range lines { fmt.Fprintf(&out, "fmt.Print(\"%s\")\n", escapeGoPrint(line)) }
    return out.String()
}
func escapeGoPrint(s string) string {
    var b strings.Builder
    for _, r := range s {
        switch r {
        case '\033': b.WriteString("\\033")
        case '\n': b.WriteString("\\n")
        case '\\': b.WriteString("\\\\")
        case '"': b.WriteString("\\\"")
        default: b.WriteRune(r)
        }
    }
    return b.String()
}

// keep explicit decoder references so imports are considered used by older toolchains
var _, _, _ = png.Decode, jpeg.Decode, gif.Decode
